import json,sys
data=json.load(sys.stdin)
steps = data['steps']
for i, s in enumerate(steps):
    msg = s.get('message')
    tcs = s.get('tool_calls')
    print('---STEP', i, s.get('source'), '---')
    if msg:
        if isinstance(msg, str):
            print('MSG:', msg[:2000])
        else:
            print('MSG:', json.dumps(msg)[:2000])
    if tcs:
        for tc in tcs:
            print('TOOLCALL:', json.dumps(tc)[:1500])
"

